 r=json.load(open(B/f'research/durance/{i}.json'));pub=r['inertia']['props']['product'];assert pub['on_stock']>0 and not pub['variants'] and '50ml' in pub['name'].replace(' ','');desc=' '.join(html.fromstring('<div>'+pub['description']+'</div>').text_content().split());pid=str(i);photo=pub['main_image']['url'];raw=urllib.request.urlopen(photo,timeout=40).read();file=pid+'.jpg';(out/file).write_bytes(raw)
